CREATE OR REPLACE FUNCTION public.seller_register_tally(p_seller uuid)
 RETURNS TABLE(all_count bigint, live_count bigint, offer_count bigint, draft_count bigint, paused_count bigint, reserved_count bigint, archived_count bigint, sold_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with base as (
    select
      l.status,
      exists (select 1 from offers o
        where o.listing_id = l.id and o.status in ('open', 'countered')) as under_offer
    from listings l
    where l.seller_id = p_seller
      and p_seller = auth.uid()
  )
  select
    count(*) as all_count,
    count(*) filter (where status = 'active' and not under_offer) as live_count,
    count(*) filter (where under_offer) as offer_count,
    count(*) filter (where status = 'draft') as draft_count,
    count(*) filter (where status = 'paused') as paused_count,
    count(*) filter (where status = 'reserved') as reserved_count,
    count(*) filter (where status = 'archived') as archived_count,
    count(*) filter (where status = 'sold') as sold_count
  from base;
$function$;

grant execute on function public.seller_register_tally(p_seller uuid) to authenticated;
grant execute on function public.seller_register_tally(p_seller uuid) to service_role;
